solutionCode:
pub fn o_classificador(nota: i32) -> String {
    if nota > 8 {
        format!("nota {} excelente", nota)
    } else if nota > 5 {
        format!("nota {} boa", nota)
    } else {
        format!("nota {} precisa estudar", nota)
    }
}

testsCode:
use desafio::o_classificador;

#[test]
fn testa_nota_nove_e_excelente() {
    assert_eq!(o_classificador(9), "nota 9 excelente");
}

#[test]
fn testa_nota_sete_e_boa() {
    assert_eq!(o_classificador(7), "nota 7 boa");
}

#[test]
fn testa_nota_tres_precisa_estudar() {
    assert_eq!(o_classificador(3), "nota 3 precisa estudar");
}
